sp_widget.client_script:
api.controller = function($scope, $location) {

    var c = this;

    // -----------------------------------------
    // INITIAL VALUES
    // -----------------------------------------

    c.data.assessment_type = 'Technical';
    c.data.saving = false;


    // -----------------------------------------
    // BACK TO DASHBOARD
    // -----------------------------------------

    c.goToDashboard = function() {

        $location.search({
            id: 'campus360_recruiter_dashboard_new'
        });

    };


    // -----------------------------------------
    // PUBLISH ASSESSMENT
    // -----------------------------------------

    c.publish = function() {

        // Basic validation
        if (!c.data.assessment_name) {

            c.data.message =
                'Please enter an assessment name.';

            return;
        }


        if (!c.data.opportunity) {

            c.data.message =
                'Please select a placement opportunity.';

            return;
        }


        c.data.saving = true;
        c.data.message = '';


        // Send data to Server Script
        c.server.update().then(function(response) {

            c.data.saving = false;


            if (response.data.success) {

                c.data.message =
                    'Assessment published successfully.';


                // Redirect to dashboard
                setTimeout(function() {

                    $location.search({
                        id: 'campus360_recruiter_dashboard_new'
                    });

                    $scope.$apply();

                }, 1000);


            } else {

                c.data.message =
                    response.data.message ||
                    'Unable to publish assessment.';

            }

        });

    };


    // -----------------------------------------
    // CANCEL
    // -----------------------------------------

    c.cancel = function() {

        c.goToDashboard();

    };

};

sp_widget.css:
/* =========================================
   CAMPUS360 - CREATE ASSESSMENT
   ========================================= */

.c360-assessment-page {
  width: 100%;
  min-height: 100vh;
  background: #f5f7fb;
  padding: 32px 20px 60px;
  box-sizing: border-box;
}

.c360-assessment-container {
  max-width: 900px;
  margin: 0 auto;
}


/* =========================================
   PAGE HEADER
   ========================================= */

.c360-page-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 22px;
  padding: 0 4px;
}

.c360-eyebrow {
  color: #5b52e8;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  margin-bottom: 6px;
}

.c360-page-header h1 {
  margin: 0;
  color: #10194f;
  font-size: 24px;
  font-weight: 600;
  line-height: 1.3;
}

.c360-page-header p {
  margin: 7px 0 0;
  color: #7b7f9c;
  font-size: 12px;
}

.c360-back {
  color: #5148df;
  font-size: 11px;
  font-weight: 500;
  text-decoration: none;
  padding-top: 5px;
}

.c360-back:hover {
  color: #3931b9;
  text-decoration: none;
}


/* =========================================
   FORM CARD
   ========================================= */

.c360-form-card {
  background: #ffffff;
  border: 1px solid #dedff0;
  border-radius: 12px;
  padding: 28px 30px 24px;
  box-shadow: 0 4px 14px rgba(50, 55, 110, 0.04);
}


/* =========================================
   FORM ROW
   ========================================= */

.c360-form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}


/* =========================================
   FIELD
   ========================================= */

.c360-field {
  margin-bottom: 18px;
}

.c360-field.full {
  width: 100%;
}

.c360-field label {
  display: block;
  margin-bottom: 7px;
  color: #111a4d;
  font-size: 11px;
  font-weight: 500;
}

.c360-field label span {
  color: #e04b5b;
}


/* =========================================
   INPUTS
   ========================================= */

.c360-field input,
.c360-field select,
.c360-field textarea {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid #cfd2df;
  border-radius: 5px;
  background: #ffffff;
  color: #18204f;
  font-size: 12px;
  font-family: inherit;
  outline: none;
  transition: border-color 0.2s ease,
              box-shadow 0.2s ease;
}

.c360-field input,
.c360-field select {
  height: 38px;
  padding: 0 11px;
}

.c360-field textarea {
  min-height: 110px;
  padding: 10px 11px;
  resize: vertical;
  line-height: 1.5;
}


/* =========================================
   PLACEHOLDER
   ========================================= */

.c360-field input::placeholder,
.c360-field textarea::placeholder {
  color: #9a9db5;
}


/* =========================================
   FOCUS
   ========================================= */

.c360-field input:focus,
.c360-field select:focus,
.c360-field textarea:focus {
  border-color: #655bea;
  box-shadow: 0 0 0 2px rgba(101, 91, 234, 0.08);
}


/* =========================================
   SELECT
   ========================================= */

.c360-field select {
  cursor: pointer;
  appearance: auto;
}


/* =========================================
   FORM ACTIONS
   ========================================= */

.c360-form-actions {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 10px;
  border-top: 1px solid #eeeeF5;
  padding-top: 18px;
  margin-top: 4px;
}


/* =========================================
   CANCEL
   ========================================= */

.c360-cancel {
  height: 36px;
  padding: 0 18px;
  border: 1px solid #d8d9e8;
  border-radius: 6px;
  background: #ffffff;
  color: #5f6383;
  font-size: 11px;
  font-weight: 500;
  cursor: pointer;
}

.c360-cancel:hover {
  background: #f7f7fc;
}


/* =========================================
   PUBLISH
   ========================================= */

.c360-publish {
  height: 36px;
  padding: 0 20px;
  border: none;
  border-radius: 6px;
  background: #5b52e8;
  color: #ffffff;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s ease,
              transform 0.1s ease;
}

.c360-publish:hover {
  background: #493fd2;
}

.c360-publish:active {
  transform: translateY(1px);
}

.c360-publish:disabled {
  opacity: 0.65;
  cursor: not-allowed;
}


/* =========================================
   MESSAGE
   ========================================= */

.c360-message {
  margin-top: 15px;
  padding: 10px 12px;
  border-radius: 6px;
  background: #f0efff;
  color: #5148df;
  font-size: 11px;
  text-align: center;
}


/* =========================================
   RESPONSIVE
   ========================================= */

@media (max-width: 700px) {

  .c360-assessment-page {
    padding: 20px 12px 40px;
  }

  .c360-page-header {
    flex-direction: column;
    gap: 10px;
  }

  .c360-form-card {
    padding: 22px 18px;
  }

  .c360-form-row {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .c360-form-actions {
    flex-direction: column-reverse;
    align-items: stretch;
  }

  .c360-cancel,
  .c360-publish {
    width: 100%;
  }

}

sp_widget.script:
(function() {

    data.success = false;
    data.message = '';


    // -----------------------------------------
    // LOAD PLACEMENT OPPORTUNITIES
    // -----------------------------------------

    data.opportunities = [];

    var opportunities = new GlideRecord(
        'x_snc_campus360_placement_opportunity'
    );

    opportunities.addQuery('status', 'Open');
    opportunities.orderBy('opportunity_title');
    opportunities.query();

    while (opportunities.next()) {

        var opportunity = {};

        opportunity.sys_id =
            opportunities.getUniqueValue();

        opportunity.title =
            opportunities.getValue('opportunity_title');

        opportunity.opportunity_id =
            opportunities.getValue('opportunity_id');

        data.opportunities.push(opportunity);
    }


    // -----------------------------------------
    // PUBLISH ASSESSMENT
    // -----------------------------------------

    if (input) {

        var assessment = new GlideRecord(
            'x_snc_campus360_student_assessment'
        );

        assessment.initialize();


        // -----------------------------------------
        // ASSESSMENT ID
        // -----------------------------------------

        var assessmentNumber =
            'ASM' +
            new GlideDateTime().getNumericValue();

        assessment.setValue(
            'assessment_id',
            assessmentNumber
        );


        // -----------------------------------------
        // ASSESSMENT NAME
        // -----------------------------------------

        assessment.setValue(
            'assessment_name',
            input.assessment_name
        );


        // -----------------------------------------
        // ASSESSMENT TYPE
        // -----------------------------------------

        if (input.assessment_type) {

            assessment.setValue(
                'assessment_type',
                input.assessment_type
            );

        }


        // -----------------------------------------
        // OPPORTUNITY
        // -----------------------------------------

        if (input.opportunity) {

            assessment.setValue(
                'opportunity',
                input.opportunity
            );

        }


        // -----------------------------------------
        // DURATION
        // -----------------------------------------

        if (input.duration) {

            assessment.setValue(
                'duration',
                input.duration
            );

        }


        // -----------------------------------------
        // MAXIMUM SCORE
        // -----------------------------------------

        if (input.maximum_score) {

            assessment.setValue(
                'maximum_score',
                input.maximum_score
            );

        }


        // -----------------------------------------
        // ASSESSMENT DATE
        // -----------------------------------------

        if (input.assessment_date) {

            assessment.setValue(
                'assessment_date',
                input.assessment_date
            );

        }


        // -----------------------------------------
        // INSTRUCTIONS
        // -----------------------------------------

        if (input.instructions) {

            assessment.setValue(
                'instructions',
                input.instructions
            );

        }


        // -----------------------------------------
        // STATUS
        // -----------------------------------------

        assessment.setValue(
            'status',
            'Published'
        );


        // -----------------------------------------
        // INSERT
        // -----------------------------------------

        var sysId = assessment.insert();


        if (sysId) {

            data.success = true;

            data.assessment_sys_id =
                sysId;

            data.message =
                'Assessment published successfully.';

        } else {

            data.success = false;

            data.message =
                'Failed to create assessment record.';

        }

    }

})();
